/**
 * 登录方式（SSO provider）图标库。
 *
 * - 内置图标：后台「SSO 登录」弹层里可挑选的 SVG 图标。品牌图标取自 simple-icons（CC0），
 *   通用语义图标（地球 / 邮箱 / 锁 …）为本文件自绘的描边图形。
 * - 自定义图片：管理员在后台上传图片后，地址写进 provider.icon_url，优先于内置图标渲染。
 *
 * 字段约定（与后端一致）：
 * - icon：小写 key（字母 / 数字 / 下划线 / 短横线），后端只校验格式，具体有哪些 key 由本文件决定；
 * - icon_url：http(s) 外链或本站 /uploads/ 路径；空值表示使用内置图标。
 */

export interface OauthIconPath {
  /** SVG path 的 d 属性 */
  d: string;
  /** 填充色（缺省 currentColor）；描边型图标为 'none' */
  fill?: string;
  /** 是否描边（true 时用 stroke=currentColor 绘制） */
  stroke?: boolean;
  /** 描边宽度（缺省 1.7） */
  width?: number;
}

export interface OauthIconDef {
  /** 图标 key（写入 provider.icon） */
  key: string;
  /** 后台选择器里的中文名 */
  label: string;
  /** SVG viewBox */
  viewBox: string;
  /** 图标路径 */
  paths: OauthIconPath[];
}

