/** key → 图标定义 */
export const OAUTH_ICON_MAP: Record<string, OauthIconDef> = Object.fromEntries(
  OAUTH_ICONS.map((i) => [i.key, i]),
);

/** provider 类型 → 默认内置图标（provider 未单独设置 icon 时按类型回退） */
export const OAUTH_TYPE_ICON: Record<string, string> = {
  github: 'github',
  google: 'google',
  generic: 'globe',
};

/**
 * 解析最终生效的内置图标 key：
 * provider.icon → 同名 slug 的内置图标（如 slug=gitee）→ 按 type 回退 → 地球。
 * 管理员填了未知 key 时不会白屏，按后面的规则继续回退。
 */
export function resolveOauthIconKey(
  icon?: string | null,
  type?: string | null,
  slug?: string | null,
): string {
  const key = String(icon ?? '').trim().toLowerCase();
  if (key && OAUTH_ICON_MAP[key]) return key;
  const slugKey = String(slug ?? '').trim().toLowerCase();
  if (slugKey && OAUTH_ICON_MAP[slugKey]) return slugKey;
  const t = String(type ?? '').trim().toLowerCase();
  return OAUTH_TYPE_ICON[t] ?? 'globe';
}

/** 取图标定义（未知 key 回退到地球） */
export function getOauthIcon(key: string): OauthIconDef {
  return OAUTH_ICON_MAP[key] ?? OAUTH_ICON_MAP.globe;
}
